// radar-4 dashboard. All values come from window.RADAR_DATA (generated by
// main.ts). Row fields, positional:
// [rank,slug,name,cat,chain,nchains,tvlM,chg7d,ageDays,impM,lowM,highM,
//  slice,net,netLow,beM,perHour,verdictIdx,playIdx,contested,vCurveM,vLocalM,vChainM,kin]
const D = window.RADAR_DATA;
const V = ["ROBUST", "FARM", "THIN", "SKIP"];
const PLAYS = [
  { play: "Vault deposit", asset: "stablecoins", action: "check the curator's allocation", fee: 1.0, hours: 2.5 },
  { play: "Liquidity pool", asset: "the pool's two assets", action: "collect fees and rebalance the range", fee: 2.0, hours: 3.5 },
  { play: "Supply & borrow", asset: "stablecoins", action: "check borrow health and rates", fee: 1.5, hours: 2.0 },
  { play: "Trade & volume", asset: "margin collateral", action: "place and manage positions", fee: 2.5, hours: 5.0 },
  { play: "Delta-neutral deposit", asset: "stablecoins", action: "check the funding rate", fee: 2.0, hours: 3.0 },
  { play: "Restake", asset: "liquid staking tokens", action: "check restaking rewards", fee: 1.0, hours: 2.0 },
  { play: "Deposit & use", asset: "stablecoins", action: "use the protocol weekly", fee: 1.5, hours: 3.0 },
];
const CHAIN_FEES = { Ethereum: 4, Base: 0.9, Arbitrum: 0.8, Optimism: 0.8, Polygon: 0.4, Solana: 0.25, "BNB Chain": 1.2, Binance: 1.2, Avalanche: 0.8, Ink: 2.5, Tron: 1.5 };
const TBILL = 6.58, HOLD = 60;
const $ = (id) => document.getElementById(id);
const money = (x) => "$" + x.toFixed(2);
const moneyM = (m) => m >= 1000 ? "$" + (m / 1000).toFixed(2) + "B" : "$" + m.toFixed(1) + "M";
const pct = (x) => (x > 0 ? "+" : "") + x.toFixed(1) + "%";
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
function season(age) { const d = age < 0 ? 365 : age; return 0.55 + 0.45 * Math.min(1, d / 730); }
function mom(chg) { if (chg === null) return 1; const f = Math.max(-0.5, Math.min(0.5, chg / 100)); return Math.max(0.9, Math.min(1.1, 1 + 0.5 * f)); }
function ageStr(age) { if (age < 0) return "—"; if (age >= 365) return (age / 365).toFixed(1) + "y"; if (age >= 30) return Math.round(age / 30) + "mo"; return age + "d"; }

// KPI strip
const verdicts = [0, 0, 0, 0];
D.rows.forEach((r) => verdicts[r[17]]++);
$("kpis").innerHTML = [
  ["198", "protocols ranked · watchlist 40/40"],
  [moneyM(D.rows[0][9]), "top implied value — " + D.rows[0][2]],
  ["×" + D.loo.miss.toFixed(2), "leave-one-out miss (flat multiple ×" + D.flatLoo.miss.toFixed(2) + ")"],
  ["×" + D.timeSplit.curveMiss.toFixed(2), "time-split miss, fit pre-2024 → test 2024+ (flat ×" + D.timeSplit.flatMiss.toFixed(2) + ")"],
  [verdicts[0] + " / " + verdicts[1] + " / " + verdicts[2] + " / " + verdicts[3], "ROBUST / FARM / THIN / SKIP"],
].map(([b, s]) => `<div class="kpi"><b>${b}</b><span>${esc(s)}</span></div>`).join("");

// Scatter: tokened comps (grey) + board implied values (amber) + fitted curve
(function scatter() {
  const W = 640, H = 300, P = { l: 46, r: 10, t: 10, b: 30 };
  const pts = D.comps.map((c) => ({ x: c[0], y: c[1], c: "#8a93a3" }));
  D.rows.forEach((r) => pts.push({ x: Math.log10(r[6] * 1e6), y: Math.log10(r[9] * 1e6), c: "#f0a832" }));
  const xs = pts.map((p) => p.x), ys = pts.map((p) => p.y);
  const x0 = Math.floor(Math.min(...xs)), x1 = Math.ceil(Math.max(...xs));
  const y0 = Math.floor(Math.min(...ys)), y1 = Math.ceil(Math.max(...ys));
  const X = (x) => P.l + ((x - x0) / (x1 - x0)) * (W - P.l - P.r);
  const Y = (y) => H - P.b - ((y - y0) / (y1 - y0)) * (H - P.t - P.b);
  const tick = (g) => g >= 9 ? "$" + Math.pow(10, g - 9) + "B" : g >= 6 ? "$" + Math.pow(10, g - 6) + "M" : "$" + Math.pow(10, g - 3) + "k";
  let s = `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Implied value versus TVL scatter">`;
  for (let gx = x0; gx <= x1; gx++) s += `<line x1="${X(gx)}" y1="${P.t}" x2="${X(gx)}" y2="${H - P.b}" stroke="#1d2432"/><text x="${X(gx)}" y="${H - 10}" fill="#9aa3b2" font-size="10" text-anchor="${gx === x1 ? "end" : gx === x0 ? "start" : "middle"}">${tick(gx)}</text>`;
  for (let gy = y0; gy <= y1; gy++) s += `<line x1="${P.l}" y1="${Y(gy)}" x2="${W - P.r}" y2="${Y(gy)}" stroke="#1d2432"/><text x="${P.l - 5}" y="${Y(gy) + 3}" fill="#9aa3b2" font-size="10" text-anchor="end">${tick(gy)}</text>`;
  const cy0 = D.curve.inter + D.curve.slope * x0, cy1 = D.curve.inter + D.curve.slope * x1;
  s += `<line x1="${X(x0)}" y1="${Y(cy0)}" x2="${X(x1)}" y2="${Y(cy1)}" stroke="#5aa2f0" stroke-dasharray="5 4" stroke-width="1.5"/>`;
  for (const p of pts) s += `<circle cx="${X(p.x).toFixed(1)}" cy="${Y(p.y).toFixed(1)}" r="${p.c === "#f0a832" ? 2.6 : 2}" fill="${p.c}"/>`;
  s += `<text x="${P.l}" y="${P.t + 8}" fill="#9aa3b2" font-size="10">x: TVL · y: mcap / implied value (log)</text></svg>`;
  $("scatter").innerHTML = s;
})();

// Histogram of implied values (log scale)
(function hist() {
  const vals = D.rows.map((r) => Math.log10(r[9] * 1e6));
  const lo = Math.floor(Math.min(...vals)), hi = Math.ceil(Math.max(...vals));
  const nb = 12, bins = new Array(nb).fill(0);
  vals.forEach((v) => { bins[Math.min(nb - 1, Math.floor(((v - lo) / (hi - lo)) * nb))]++; });
  const mx = Math.max(...bins), W = 640, H = 190, bw = (W - 40) / nb;
  let s = `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Histogram of implied values">`;
  bins.forEach((b, i) => {
    const h = (b / mx) * (H - 40);
    s += `<rect x="${20 + i * bw + 2}" y="${H - 26 - h}" width="${bw - 4}" height="${h}" fill="#f0a832"/>`;
    if (i % 3 === 0) s += `<text x="${20 + i * bw + bw / 2}" y="${H - 8}" fill="#9aa3b2" font-size="10" text-anchor="middle">$${Math.pow(10, lo + ((i + 0.5) / nb) * (hi - lo) - 6).toFixed(0)}M</text>`;
  });
  s += `<text x="20" y="14" fill="#9aa3b2" font-size="10">count per log bin · peak ${mx} rows</text></svg>`;
  $("hist").innerHTML = s;
})();

// Farm Next: top 10 by net $/hour at the band's low end, only netLow > 0
(function farmNext() {
  const list = D.rows
    .map((r) => ({ r, h: r[14] / PLAYS[r[18]].hours }))
    .filter((o) => o.r[14] > 0)
    .sort((a, b) => b.h - a.h)
    .slice(0, 10);
  $("farmnext").innerHTML = list.map((o) =>
    `<li><b>#${o.r[0]} ${esc(o.r[2])}</b> — ${money(o.h)}/h at the low end, net ${money(o.r[14])} on $1,000 · <span class="badge v${o.r[17]}">${V[o.r[17]]}</span></li>`).join("");
})();

// Audit tab
$("auditline").textContent = `${D.nTotal} protocols: ${D.nRanked} ranked + ${D.nTokened} record a token already + ${D.setAsideTotal} set aside with a reason.`;
$("auditrows").innerHTML = D.audit.map(([reason, n]) => `<tr><td>${esc(reason)}</td><td class="num">${n}</td></tr>`).join("") +
  `<tr><td><b>Total set aside</b></td><td class="num"><b>${D.setAsideTotal}</b></td></tr>`;

// Calibration tab
$("method").innerHTML = `
<p><b>Size curve</b> — OLS on log10(mcap) vs log10(TVL) over ${D.comps.length} tokened comparables:
log10(mcap) = ${D.curve.inter} + ${D.curve.slope}·log10(TVL), R² = ${D.curve.r2}.
Global band ×${D.curve.globalBand[0]}–×${D.curve.globalBand[1]} (P25–P75 of residuals).</p>
<p><b>Per-category calibration</b> — each category's band is its own leave-one-out P25–P75, and its
category adjustment is the shrunk median residual (n/(n+20), clamped ±0.40 log points, min 6 comps).</p>
<p><b>Ensemble</b> — three pricings per protocol: (i) the size curve, (ii) the local-comps median
mcap/TVL (same category, TVL within 10×, else any category, else the global median), (iii) a
chain-breadth model, value ∝ TVL^slope × chains^gamma, gamma fitted at runtime. Implied value =
lower quartile of the three, × seasoning (0.55→1.00 over 730 days with no token) × momentum
(1 + 0.5 × 7-day change, clamped [0.90, 1.10]) × 0.5 when a same-family protocol's token already
trades (kin). Rows where the three models span more than 3× are flagged contested.</p>
<p><b>Backtests (computed at runtime, not placeholders)</b> — leave-one-out over all ${D.comps.length}
comps: median miss ×${D.loo.miss} vs a flat mcap/TVL multiple ×${D.flatLoo.miss};
within 3× ${(D.loo.within3 * 100).toFixed(0)}% (flat ${(D.flatLoo.within3 * 100).toFixed(0)}%),
within 10× ${(D.loo.within10 * 100).toFixed(0)}% (flat ${(D.flatLoo.within10 * 100).toFixed(0)}%).
Time split — fit on ${D.timeSplit.nTrain} tokens listed before 2024, test on ${D.timeSplit.nTest} listed
2024 or later: miss ×${D.timeSplit.curveMiss} vs flat ×${D.timeSplit.flatMiss};
within 3× ${(D.timeSplit.curveWithin3 * 100).toFixed(0)}% (flat ${(D.timeSplit.flatWithin3 * 100).toFixed(0)}%).</p>
<p><b>Farm maths</b> — $1,000 ticket, 60-day hold, slice = 10% of implied value × $1,000 / TVL.
Fees = chain fee + play fee (Ethereum $4.00, Base $0.90, Arbitrum/Optimism/Avalanche $0.80,
BNB Chain $1.20, Solana $0.25, Ink $2.50, Tron $1.50, else $1.50) plus the play fee.
T-bill opportunity cost $6.58 (4% for 60 days). ROBUST pays even at the category band's low end;
FARM pays after every cost; THIN beats cash fees only; SKIP means fees eat the drop.
Break-even = (fees + $6.58) × TVL / 100.</p>`;
$("calibrows").innerHTML = D.calibration.map(([cat, n, miss, blo, bhi, adj]) =>
  `<tr><td>${esc(cat)}</td><td class="num">${n}</td><td class="num">×${miss.toFixed(2)}</td><td class="num">×${blo.toFixed(2)}–×${bhi.toFixed(2)}</td><td class="num">${adj > 0 ? "+" : ""}${adj.toFixed(2)}</td></tr>`).join("");

// Board table: filters + sorting + detail dialog
const state = { q: "", cat: "", chain: "", v: "", k: 0, dir: 1 };
const cats = [...new Set(D.rows.map((r) => r[3]))].sort();
const chains = [...new Set(D.rows.map((r) => r[4]))].sort();
$("fcat").innerHTML += cats.map((c) => `<option>${esc(c ?? "")}</option>`).join("");
$("fchain").innerHTML += chains.map((c) => `<option>${esc(c ?? "")}</option>`).join("");
function filtered() {
  return D.rows.filter((r) =>
    (state.q === "" || (r[2] + " " + r[1]).toLowerCase().includes(state.q)) &&
    (state.cat === "" || r[3] === state.cat) &&
    (state.chain === "" || r[4] === state.chain) &&
    (state.v === "" || String(r[17]) === state.v));
}
function render() {
  const list = filtered().slice().sort((a, b) => {
    const k = state.k, av = a[k], bv = b[k];
    const c = (av === null ? -1e18 : av) < (bv === null ? -1e18 : bv) ? -1 : (av === null ? -1e18 : av) > (bv === null ? -1e18 : bv) ? 1 : 0;
    return c * state.dir || (a[0] - b[0]);
  });
  $("count").textContent = `${list.length} of ${D.rows.length} rows`;
  $("rows").innerHTML = list.map((r) => {
    const chg = r[7] === null ? "—" : `<span class="${r[7] >= 0 ? "up" : "down"}">${pct(r[7])}</span>`;
    return `<tr data-slug="${r[1]}"><td class="num">${r[0]}</td><td><b>${esc(r[2])}</b>${r[19] ? ' <span class="badge v3">contested</span>' : ""}</td>
<td>${esc(r[3] ?? "—")}</td><td>${esc(r[4] ?? "—")}${r[5] > 1 ? " +" + (r[5] - 1) : ""}</td>
<td class="num">${moneyM(r[6])}</td><td class="num">${chg}</td><td class="num">${ageStr(r[8])}</td>
<td class="num"><b>${moneyM(r[9])}</b></td><td class="num">${moneyM(r[10])}–${moneyM(r[11])}</td>
<td class="num">${money(r[12])}</td><td class="num ${r[13] >= 0 ? "up" : "down"}">${money(r[13])}</td>
<td class="num">${money(r[16])}</td><td><span class="badge v${r[17]}">${V[r[17]]}</span></td>
<td>${r[19] ? '<span class="bad">yes</span>' : "—"}</td></tr>`;
  }).join("");
}
document.querySelectorAll("#board th").forEach((th) => th.addEventListener("click", () => {
  const k = Number(th.dataset.k);
  if (state.k === k) state.dir *= -1; else { state.k = k; state.dir = 1; }
  render();
}));
$("q").addEventListener("input", (e) => { state.q = e.target.value.trim().toLowerCase(); render(); });
$("fcat").addEventListener("change", (e) => { state.cat = e.target.value; render(); });
$("fchain").addEventListener("change", (e) => { state.chain = e.target.value; render(); });
$("fverdict").addEventListener("click", (e) => {
  if (e.target.tagName !== "BUTTON") return;
  document.querySelectorAll("#fverdict button").forEach((b) => b.classList.remove("on"));
  e.target.classList.add("on");
  state.v = e.target.dataset.v; render();
});
$("rows").addEventListener("click", (e) => {
  const tr = e.target.closest("tr");
  if (tr) openDetail(tr.dataset.slug);
});
function openDetail(slug) {
  const r = D.rows.find((x) => x[1] === slug);
  if (!r) return;
  const play = PLAYS[r[18]];
  const fee = (CHAIN_FEES[r[4]] ?? 1.5) + play.fee;
  const trio = [r[20], r[21], r[22]].sort((a, b) => a - b);
  const q1 = trio[0] + 0.5 * (trio[1] - trio[0]);
  const s = season(r[8]), m = mom(r[7]);
  const rec = q1 * s * m * (r[23] ? 0.5 : 1);
  const ok = Math.abs(rec - r[9]) / r[9] < 0.02;
  const steps = D.steps.map((t) => t
    .replaceAll("{name}", r[2]).replaceAll("{chain}", r[4] ?? "its main chain").replaceAll("{play}", play.play)
    .replaceAll("{asset}", play.asset).replaceAll("{action}", play.action)
    .replaceAll("{fee}", money(fee)).replaceAll("{tbill}", money(TBILL))
    .replaceAll("{hours}", String(play.hours)).replaceAll("{hold}", String(HOLD)));
  $("detailbody").innerHTML = `
<h2>#${r[0]} ${esc(r[2])}</h2>
<p class="note">${esc(r[3] ?? "—")} · ${esc(r[4] ?? "—")}${r[5] > 1 ? " +" + (r[5] - 1) + " chains" : ""} · TVL ${moneyM(r[6])} · 7D ${r[7] === null ? "—" : pct(r[7])} · no token for ${ageStr(r[8])}</p>
<div class="kv">
<div><span>Implied value</span><br><b>${moneyM(r[9])}</b></div>
<div><span>Category band</span><br><b>${moneyM(r[10])} – ${moneyM(r[11])}</b></div>
<div><span>Slice per $1k</span><br><b>${money(r[12])}</b></div>
<div><span>Verdict</span><br><span class="badge v${r[17]}">${V[r[17]]}</span>${r[19] ? ' <span class="badge v3">contested</span>' : ""}</div>
<div><span>Net / net at low end</span><br><b>${money(r[13])} / ${money(r[14])}</b></div>
<div><span>Break-even / $/hour</span><br><b>${moneyM(r[15])} / ${money(r[16])}</b></div>
</div>
<h3>Model breakdown — recompute it yourself</h3>
<table><tbody>
<tr><td>Size curve (i)</td><td class="num">${moneyM(r[20])}</td></tr>
<tr><td>Local-comps multiple (ii)</td><td class="num">${moneyM(r[21])}</td></tr>
<tr><td>Chain-breadth model (iii)</td><td class="num">${moneyM(r[22])}</td></tr>
<tr><td>Lower quartile of the three</td><td class="num">${moneyM(q1)}</td></tr>
<tr><td>× seasoning ${s.toFixed(3)}</td><td class="num">×${s.toFixed(3)}</td></tr>
<tr><td>× momentum ${m.toFixed(3)}</td><td class="num">×${m.toFixed(3)}</td></tr>
<tr><td>× kin ${r[23] ? "0.5 (same-family token trades)" : "1.0"}</td><td class="num">×${r[23] ? "0.5" : "1.0"}</td></tr>
<tr><td><b>Recomputed implied</b></td><td class="num"><b>${moneyM(rec)}</b> <span class="${ok ? "ok" : "bad"}">${ok ? "✓ matches" : "✗ mismatch"}</span></td></tr>
</tbody></table>
<h3>Farm plan — $1,000 ticket, ${HOLD}-day hold</h3>
<ol>${steps.map((x) => `<li>${esc(x)}</li>`).join("")}</ol>
<p class="note">Verdict maths: slice ${money(r[12])} − fees ${money(fee)} − T-bill ${money(TBILL)} = net ${money(r[13])};
at the band's low end ${money(r[14])}. Break-even implied value ${moneyM(r[15])} — the token must be worth at
least that for the farm to pay. Hands-on time ${play.hours} hours, so ${money(r[16])}/hour.</p>`;
  $("detail").showModal();
  $("detail").scrollTop = 0;
}
$("closedetail").addEventListener("click", () => $("detail").close());

// Tabs
document.querySelectorAll(".tabs button").forEach((b) => b.addEventListener("click", () => {
  document.querySelectorAll(".tabs button").forEach((x) => x.classList.remove("on"));
  b.classList.add("on");
  ["board", "audit", "calib"].forEach((t) => { $("tab-" + t).hidden = t !== b.dataset.tab; });
}));

// Screenshot modes: ?shot=board|detail|filtered|calibration
const shot = new URLSearchParams(location.search).get("shot");
if (shot === "detail") openDetail(D.rows[0][1]);
else if (shot === "filtered") { state.v = "1"; document.querySelectorAll("#fverdict button").forEach((b) => b.classList.toggle("on", b.dataset.v === "1")); render(); document.querySelector(".filters").scrollIntoView(); }
else if (shot === "calibration") document.querySelector('[data-tab="calib"]').click();
render();
